test "t08 xor fold" {
    const a = [_]u8{ 0x01, 0x02, 0x03 };
    try std.testing.expectEqual(@as(u8, 0), xorFold(&a));
    const b = [_]u8{ 0x0f, 0xf0 };
    try std.testing.expectEqual(@as(u8, 0xff), xorFold(&b));
    const empty = [_]u8{};
    try std.testing.expectEqual(@as(u8, 0), xorFold(&empty));
}
